    findLastIndex(predicate: (value: number, index: number, array: FloatArray) => unknown, thisArg?: any): number;
    forEach(callbackfn: (value: number, index: number, array: FloatArray) => void, thisArg?: any): void;
    includes(searchElement: number, fromIndex?: number): boolean;
