    set(array: ArrayLike<number>, offset?: number): void;
    slice(start?: number, end?: number): FloatArray;
    some(predicate: (value: number, index: number, array: FloatArray) => unknown, thisArg?: any): boolean;
    sort(compareFn?: (a: number, b: number) => number): this;
